test_suite:
function mountObserved() {
  const state: { isVisible?: boolean } = {};
  function Target() {
    const { ref, isVisible } = useIntersection();
    state.isVisible = isVisible;
    return <div ref={ref as any} />;
  }
  const view = render(<Target />);
  return { state, el: view.container.firstChild, unmount: view.unmount };
}

function stubObserver() {
  const observer = { cb: undefined as any, observe: vi.fn(), disconnect: vi.fn() };
  vi.stubGlobal('IntersectionObserver', vi.fn((fn: IntersectionObserverCallback) => {
    observer.cb = fn;
    return { observe: observer.observe, disconnect: observer.disconnect };
  }));
  return observer;
}

afterEach(() => {
  vi.unstubAllGlobals();
});

test('isVisible starts as false', () => {
  const { result } = renderHook(() => useIntersection());
  expect(result.current.isVisible).toBe(false);
});

test('returns a ref object', () => {
  const { result } = renderHook(() => useIntersection());
  expect(result.current.ref).toHaveProperty('current');
});

test('observes the attached element', () => {
  const observer = stubObserver();
  const { el } = mountObserved();
  expect(observer.observe).toHaveBeenCalledWith(el);
});

test('isVisible becomes true when intersection entry isIntersecting', () => {
  const observer = stubObserver();
  const { state } = mountObserved();
  act(() => observer.cb([{ isIntersecting: true }], {}));
  expect(state.isVisible).toBe(true);
});

test('isVisible becomes false when no longer intersecting', () => {
  const observer = stubObserver();
  const { state } = mountObserved();
  act(() => observer.cb([{ isIntersecting: true }], {}));
  act(() => observer.cb([{ isIntersecting: false }], {}));
  expect(state.isVisible).toBe(false);
});

// __hidden__
test('disconnects observer on unmount', () => {
  const observer = stubObserver();
  const { unmount } = mountObserved();
  unmount();
  expect(observer.disconnect).toHaveBeenCalled();
});

solution:
import { useRef, useState, useEffect } from 'react';

export function useIntersection(options?: IntersectionObserverInit) {
  const ref = useRef<HTMLElement>(null);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) => {
      setIsVisible(entry.isIntersecting);
    }, options);
    observer.observe(el);
    return () => observer.disconnect();
  }, [options]);

  return { ref, isVisible };
}
